import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { FlightService } from '../../services/flight.service';
import { BookingService } from '../../services/booking.service';
import { Flight } from '../../models/flight.model';

@Component({
  selector: 'app-flight-booking',
  templateUrl: './flight-booking.component.html',
  styleUrls: ['./flight-booking.component.css']
})
export class FlightBookingComponent implements OnInit {
  bookingForm!: FormGroup;
  flights: Flight[] = [];
  selectedFlight: Flight | null = null;
  isSubmitting = false;
  successMessage = '';
  errorMessage = '';

  constructor(
    private fb: FormBuilder,
    private flightService: FlightService,
    private bookingService: BookingService,
    private route: ActivatedRoute,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.initForm();
    this.loadFlights();
  }

  initForm(): void {
    this.bookingForm = this.fb.group({
      flightId: ['', Validators.required],
      passengerName: ['', [Validators.required, Validators.minLength(3)]],
      passportNumber: ['', [Validators.required, Validators.pattern(/^[A-Z0-9]{6,12}$/i)]],
      cabinClass: ['Economy', Validators.required],
      seatNumber: ['14B', Validators.required],
      mealPreference: ['Standard', Validators.required],
      luggageCount: [1, [Validators.required, Validators.min(0), Validators.max(4)]]
    });
  }

  loadFlights(): void {
    this.flightService.getFlights().subscribe({
      next: (res) => {
        this.flights = res.flights;
        const flightIdParam = this.route.snapshot.queryParamMap.get('flightId');
        if (flightIdParam) {
          this.bookingForm.patchValue({ flightId: parseInt(flightIdParam, 10) });
          this.onFlightChange();
        }
      }
    });
  }

  onFlightChange(): void {
    const id = parseInt(this.bookingForm.get('flightId')?.value, 10);
    this.selectedFlight = this.flights.find(f => f.id === id) || null;
  }

  onSubmit(): void {
    if (this.bookingForm.invalid) {
      this.bookingForm.markAllAsTouched();
      return;
    }

    this.isSubmitting = true;
    this.errorMessage = '';
    this.successMessage = '';

    this.bookingService.createBooking(this.bookingForm.value).subscribe({
      next: (res) => {
        this.isSubmitting = false;
        this.successMessage = `Reservation confirmed! Booking Reference (PNR): ${res.booking.pnrNumber}`;
        setTimeout(() => {
          this.router.navigate(['/my-bookings']);
        }, 2500);
      },
      error: (err) => {
        this.isSubmitting = false;
        this.errorMessage = err.error?.message || 'Flight booking failed. Please try again.';
      }
    });
  }
}
<div class="container page-container">
  <div class="form-wrapper">
    <div class="form-header">
      <h1>Flight Ticket Reservation</h1>
      <p>Reserve seats and generate boarding pass & luggage tags.</p>
    </div>

    <div *ngIf="successMessage" class="alert-success">
      ✓ {{ successMessage }}
    </div>
    <div *ngIf="errorMessage" class="alert-error">
      ✕ {{ errorMessage }}
    </div>

    <form [formGroup]="bookingForm" (ngSubmit)="onSubmit()">
      <!-- Flight Selection -->
      <div class="form-group">
        <label class="form-label">Select Flight Route *</label>
        <select class="form-control" formControlName="flightId" (change)="onFlightChange()">
          <option value="" disabled>-- Select Available Flight --</option>
          <option *ngFor="let f of flights" [value]="f.id">
            {{ f.flightNumber }} - {{ f.airline }} ({{ f.originCode }} → {{ f.destinationCode }}) [{{ f.status }}]
          </option>
        </select>
        <div *ngIf="bookingForm.get('flightId')?.touched && bookingForm.get('flightId')?.invalid" class="error-text">
          Please select a flight.
        </div>
      </div>

      <!-- Selected Flight Info Banner -->
      <div *ngIf="selectedFlight" class="selected-flight-preview">
        <div><strong>Schedule:</strong> {{ selectedFlight?.scheduledDeparture | date:'medium' }}</div>
        <div><strong>Terminal / Gate:</strong> {{ selectedFlight?.terminal }} (Gate {{ selectedFlight?.gate }})</div>
        <div><strong>Economy Fare:</strong> ${{ selectedFlight?.economyFare }} | <strong>Business:</strong> ${{ selectedFlight?.businessFare }}</div>
      </div>

      <div class="form-row">
        <div class="form-group flex-1">
          <label class="form-label">Passenger Full Name (as on Passport) *</label>
          <input type="text" class="form-control" formControlName="passengerName" placeholder="e.g. Captain John Miller" />
          <div *ngIf="bookingForm.get('passengerName')?.touched && bookingForm.get('passengerName')?.invalid" class="error-text">
            Full name is required (min 3 chars).
          </div>
        </div>

        <div class="form-group flex-1">
          <label class="form-label">Passport / National ID Number *</label>
          <input type="text" class="form-control" formControlName="passportNumber" placeholder="e.g. P89234120" />
          <div *ngIf="bookingForm.get('passportNumber')?.touched && bookingForm.get('passportNumber')?.invalid" class="error-text">
            Valid passport number required (6-12 alphanumeric).
          </div>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group flex-1">
          <label class="form-label">Cabin Class *</label>
          <select class="form-control" formControlName="cabinClass">
            <option value="Economy">Economy Class</option>
            <option value="Premium Economy">Premium Economy</option>
            <option value="Business">Business Class</option>
            <option value="First Class">First Class</option>
          </select>
        </div>

        <div class="form-group flex-1">
          <label class="form-label">Seat Preference *</label>
          <select class="form-control" formControlName="seatNumber">
            <option value="12A (Window)">12A (Window - Front)</option>
            <option value="14B (Aisle)">14B (Aisle - Mid)</option>
            <option value="20F (Window)">20F (Window - Wing)</option>
            <option value="25C (Extra Legroom)">25C (Extra Legroom)</option>
          </select>
        </div>
      </div>

      <div class="form-row">
        <div class="form-group flex-1">
          <label class="form-label">Meal Preference</label>
          <select class="form-control" formControlName="mealPreference">
            <option value="Standard">Standard Airline Meal</option>
            <option value="Vegetarian">Vegetarian (Asian / Western)</option>
            <option value="Vegan">Strict Vegan</option>
            <option value="Halal">Halal Certified</option>
            <option value="Kosher">Kosher Certified</option>
            <option value="Gluten-Free">Gluten-Free</option>
          </select>
        </div>

        <div class="form-group flex-1">
          <label class="form-label">Checked Baggage Count (Max 4 bags)</label>
          <input type="number" class="form-control" formControlName="luggageCount" min="0" max="4" />
        </div>
      </div>

      <div class="form-actions">
        <button type="submit" class="btn btn-primary btn-block" [disabled]="isSubmitting">
          {{ isSubmitting ? 'Confirming Reservation...' : 'Complete Flight Booking' }}
        </button>
      </div>
    </form>
  </div>
</div>
